                    ref("dwd", "label"),
                ],
            )
        )
        self.assertEqual(
            [impact["seed"] for impact in result["impacts"]],
            [ref("dwd", "label"), ref("ods", "name"), ref("dwd", "label")],
        )
        self.assertEqual(
            result["impacts"][0], result["impacts"][2]
        )

    def test_self_loop_makes_seed_its_own_downstream(self):
